:root{font-family:Inter,system-ui,sans-serif;color:#162238;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}.shell{display:flex;min-height:100vh}aside{width:240px;background:#10233f;color:#dce8fb;padding:28px 16px}aside h1{margin:0;color:#fff;font-size:24px}aside p{margin:6px 0 24px;color:#89a4ca}aside button{display:block;width:100%;border:0;background:transparent;color:#b9c9e1;text-align:left;padding:12px;border-radius:8px;margin:3px 0;cursor:pointer}aside button.active,aside button:hover{background:#1f4d83;color:#fff}main{flex:1}header{height:72px;background:#fff;border-bottom:1px solid #e5ebf3;display:flex;justify-content:space-between;align-items:center;padding:0 36px;font-weight:600}.crumb{color:#8794a8}.user{color:#53657f}.content{padding:36px;max-width:1200px}h2{font-size:28px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.cards article,.panel{background:#fff;border-radius:14px;padding:22px;box-shadow:0 4px 16px #253b5d0b}.cards small,.cards span{display:block;color:#7888a1}.cards strong{display:block;font-size:32px;margin:15px 0}.cards span{font-size:12px;color:#26a269}.panel{margin-top:24px;min-height:180px}.panel button{background:#2468d8;color:#fff;border:0;border-radius:7px;padding:10px 18px;cursor:pointer}code{color:#a54d20}</style>
